import { Headphones, Play, Volume2 } from 'lucide-react';
import type { SavedVocabularySource, SavedVocabularyWord } from '../../lib/api';
import { speakEnglishText } from '../../lib/speech';

export function wordTime(seconds: number) {
  return `${Math.floor(seconds / 60).toString().padStart(2, '0')}:${Math.floor(seconds % 60).toString().padStart(2, '0')}`;
}
export function StatusBadge({ word }: { word: SavedVocabularyWord }) {
  const mastered = word.status === 'MASTERED';
  const due = new Date(word.nextReviewAt).getTime() <= Date.now();
  return <span className={`vw-badge ${mastered ? 'vw-mastered' : due ? 'vw-due' : ''}`}>{mastered ? 'Đã nhớ' : due ? 'Cần ôn' : 'Mới lưu'}</span>;
}
export function SpeakButton({ text, label }: { text: string; label?: string }) {
  return <button type="button" className="vw-icon-button" onClick={() => speakEnglishText(text, 0.85)} aria-label={label ?? `Nghe phát âm ${text}`}><Volume2 size={22} /></button>;
}
export function SourceLink({ source, onReplay, busy = false }: { source: SavedVocabularySource; onReplay: () => void; busy?: boolean }) {
  return <button type="button" className="vw-source" onClick={onReplay} disabled={busy} aria-label={`Nghe câu gốc trong ${source.title} tại ${wordTime(source.startTime)}`}><span className="vw-source-icon"><Headphones size={24} /></span><span><strong>{source.title}</strong><small><Play size={14} /> {busy ? 'Đang mở bài nghe…' : `Nghe câu gốc · ${wordTime(source.startTime)}`}</small></span></button>;
}
export function ContextSentence({ word, source }: { word: SavedVocabularyWord; source?: SavedVocabularySource }) {
  if (!source) return null;
  const escaped = word.word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const parts = source.sentence.split(new RegExp(`(${escaped})`, 'gi'));
  return <><p className="vw-sentence" lang="en">{parts.map((part, i) => part.toLowerCase() === word.word.toLowerCase() ? <mark key={i}>{part}</mark> : part)}</p><p className="vw-translation">{source.sentenceTranslation}</p></>;
}
